const n = this.node;
const a = n && n.closest ? n.closest('a[href]') : null;
if (!a || a.dataset.hibV2Ready !== '1') return false;
let g;
try { g = JSON.parse(a.dataset.tihGallery || '[]'); } catch (e) { return false; }
if (!Array.isArray(g) || !g.length) return false;
const v = g.filter(u => typeof u === 'string' && /^https:\/\/img\.dlsite\.jp\//i.test(u));
if (!v.length) return false;
console.log('[HIB-v2-Imagus-Gallery] GALLERY READY:', v.length);
return v.map(u => [u]);
